// Ambient declarations for Swiper's CSS subpath imports.
// Next.js + the bundler handle the actual CSS at build time; TypeScript
// just needs to know these side-effect import paths are valid modules.
declare module 'swiper/css'
declare module 'swiper/css/pagination'
declare module 'swiper/css/navigation'
declare module 'swiper/css/grid'
declare module 'swiper/css/autoplay'
